const menu=document.querySelector('.menu'),nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',open);nav.classList.toggle('open',open)});nav.addEventListener('click',e=>{if(e.target.closest('a')){nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}});const form=document.querySelector('form'),input=document.querySelector('#contact-value');let previousChannel='whatsapp';const contactValues={whatsapp:'',email:''};document.querySelectorAll('[name=canal]').forEach(r=>r.addEventListener('change',()=>{contactValues[previousChannel]=input.value;previousChannel=r.value;const mail=r.value==='email';input.type=mail?'email':'tel';input.autocomplete=mail?'email':'tel';input.value=contactValues[r.value];input.minLength=mail?5:7;document.querySelector('#contact-label').textContent=mail?'Correo electrónico':'Número de WhatsApp'}));form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;form.hidden=true;const result=document.querySelector('#resultado');result.hidden=false;result.focus()});document.querySelector('#volver').addEventListener('click',()=>{document.querySelector('#resultado').hidden=true;form.hidden=false;form.querySelector('input').focus()});